from pydantic import BaseModel, Field, ValidationError
from uuid import uuid4
from datetime import datetime
import hashlib

class SearchArgs(BaseModel):
    query: str = Field(min_length=2, max_length=200)
    category: str = Field(default="all", pattern=r"^(all|policy|tech|sales)$")
    max_results: int = Field(default=5, ge=1, le=20)

class CreateOrderArgs(BaseModel):
    product_id: str = Field(min_length=1)
    quantity: int = Field(ge=1, le=100)
    idempotency_key: str = Field(min_length=8)

def execute_search_tool(raw_args: dict, user):
    """查询类工具：参数校验 + 权限校验 + 执行"""
    try:
        args = SearchArgs.model_validate(raw_args)
    except ValidationError as exc:
        # 可恢复错误：回填给模型修正
        return {"ok": False, "retryable": True, "error": str(exc)}

    if not can_read_category(user, args.category):
        # 不可恢复错误：不让模型绕过
        return {"ok": False, "retryable": False, "error": "permission denied"}

    docs = search_documents(args.query, args.category, args.max_results)
    return {"ok": True, "documents": docs}

def execute_create_order(raw_args: dict, user):
    """副作用工具：额外幂等检查 + 审计"""
    try:
        args = CreateOrderArgs.model_validate(raw_args)
    except ValidationError as exc:
        return {"ok": False, "retryable": True, "error": str(exc)}

    if not can_create_order(user):
        return {"ok": False, "retryable": False, "error": "permission denied"}

    # 幂等键检查：防止重试导致重复下单
    existing = find_order_by_idempotency_key(args.idempotency_key)
    if existing:
        return {"ok": True, "order_id": existing.id, "cached": True}

    order = create_order(user, args.product_id, args.quantity)
    save_idempotency_record(args.idempotency_key, order.id)
    audit_log("create_order", user, args, order.id)
    return {"ok": True, "order_id": order.id}
